UPDATE "products" SET "seo_description" = 'Continuous length rubber-cork rolls offering seamless gasket fabrication, reduced scrap rates, and uniform thickness across large spans.', "image_alt" = "name" || ' from United Rubber Cork', "introduction" = 'Continuous length rubber-cork rolls offering seamless gasket fabrication, reduced scrap rates, and uniform thickness across large spans.', "features" = '["Continuous length eliminates intermediate dovetail joints in perimeter gaskets","Precision thickness tolerance across entire roll width for uniform seal compression","Highly pliable and crack-resistant during die-cutting and high-speed stamping","Formulated with oil-resistant Nitrile and weather-resistant Neoprene polymers"]'::jsonb, "applications" = '["High-Volume Automated Die-Cut Automotive Gaskets","Enclosure Weatherproofing & Electronic Cabinet Sealing","Continuous Flange Strip Gaskets for Ducting & Pipe Lines","Vibration Isolation Tape & Anti-Squeak Liners"]'::jsonb WHERE "slug" IN ('rubber-cork-rolls');--> statement-breakpoint
